node --max-old-space-size=768 --input-type=module <<'NODE'
import fs from 'node:fs';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { gunzipSync } from 'node:zlib';
import { createRequire } from 'node:module';
import { resolve, dirname } from 'node:path';
import { buildSync } from 'esbuild';
const sha = s => createHash('sha256').update(s).digest('hex');
const sourcePath = 'src/learn/report.ts';
const baseline = JSON.parse(fs.readFileSync('docs/remediation/design/W32.02/baseline.json','utf8'));
const original = baseline.owned.find(f=>f.path===sourcePath);
const before = gunzipSync(Buffer.from(original.content_gzip_base64,'base64')).toString();
assert.equal(sha(before),original.sha256);
const after = fs.readFileSync(sourcePath,'utf8');
assert.notEqual(sha(after),sha(before));
for(const pin of baseline.pins.filter(f=>f.role!=='output')) assert.equal(sha(fs.readFileSync(pin.path)),pin.sha256,pin.path);
const require = createRequire(resolve(sourcePath));
function bundle(contents) {
  const result=buildSync({stdin:{contents,loader:'ts',sourcefile:'report.ts',resolveDir:dirname(resolve(sourcePath))},bundle:true,write:false,platform:'node',format:'cjs',tsconfig:'tsconfig.json',metafile:true,logLevel:'silent'});
  const module={exports:{}};
  new Function('module','exports','require',result.outputFiles[0].text)(module,module.exports,require);
  return {api:module.exports,inputs:Object.keys(result.metafile.inputs).sort()};
}
const old=bundle(before),current=bundle(after);
assert.deepEqual(old.inputs,current.inputs);
const dependencies=old.inputs.filter(path=>path!==sourcePath&&fs.existsSync(path)).map(path=>({path,sha256:sha(fs.readFileSync(path))}));
const T0=Date.UTC(2026,8,3,12),policy={name:'learning',...old.api.DEFAULT_POLICY};
function input(n) {
  const decisions=Array.from({length:n},(_,j)=>{
    const visitor='v'+Math.floor(j/5),slot=j%2?'tile':'hero';
    return {decision_id:'synthetic:'+j,tenant:'demo',brand:'demo',visitor_id:visitor,session_id:visitor,identity_anchor:'visitor',ts:T0+j*1000,
      page:'home',slot,position:0,item_id:'item'+j%10,customer_item_id:'cms'+j%10,candidates:[],
      cell:{channel:'direct',visit_bucket:'1',region:'US-NY',affinity:null},arm:Math.floor(j/5)%4===0?'default':'personalized',explored:j%7===0,authority:'engine',
      versions:{config:1,lift:0,prior:0,policy:1},config_label:'v1',explain:{drivers:[],score_base:0,lift:null,score_final:0}};
  });
  const outcomes=Array.from({length:n/5},(_,g)=>{
    const d=decisions[g*5+4];
    return {outcome_id:'synthetic-outcome:'+g,tenant:'demo',brand:'demo',visitor_id:d.visitor_id,session_id:d.session_id,
      ts:d.ts+1000,type:'click',event:'click',item_id:d.item_id,slot:null,value:null,currency:null,margin:null,products:null,arm:null};
  });
  return {tenant:'demo',brand:'demo',date:'2026-09-03',learning:policy,reporting:old.api.presetPolicies(policy),
    learn:{holdout:{share:0.1,salt:'',arms:['default']},slots:{hero:{reward:'click',exploration:{mode:'rotation',share:0.5,floor:50}},tile:{reward:'click',exploration:{mode:'off'}}}},
    decisions,outcomes,now:T0+24*3600_000,truncated:false};
}
const results=[];
for(const size of [2000,10000]) {
  const i=input(size),inputHash=sha(JSON.stringify(i)),timings={before:[],after:[]};
  let expected=null;
  const run=which=>{
    const started=performance.now();
    const result=(which==='before'?old.api:current.api).buildReport(i);
    const elapsed=performance.now()-started;
    const bytes=JSON.stringify(result);
    if(expected===null)expected=bytes;else assert.equal(bytes,expected,'Full report output differs: '+which+' '+size);
    return elapsed;
  };
  run('before');run('after');
  for(let sample=0;sample<3;sample++)for(const which of sample%2?['after','before']:['before','after'])timings[which].push(run(which));
  assert.equal(sha(JSON.stringify(i)),inputHash,'Input changed');
  const median=values=>[...values].sort((a,b)=>a-b)[1];
  results.push({decisions:size,outcomes:size/5,visitors:size/5,policies:5,slots:2,items:10,decisions_per_visitor:5,
    warmup_pairs:1,measured_pairs:3,input_sha256:inputHash,input_unchanged:true,full_output_equal_every_run:true,output_sha256:sha(expected),output_bytes:Buffer.byteLength(expected),
    milliseconds:timings,median_ms:{before:median(timings.before),after:median(timings.after)}});
}
assert.equal(sha(fs.readFileSync(sourcePath)),sha(after));
for(const pin of dependencies)assert.equal(sha(fs.readFileSync(pin.path)),pin.sha256,pin.path);
console.log(JSON.stringify({at:new Date().toISOString(),runtime:process.version,platform:process.platform,arch:process.arch,
  comparison:'Retained actual pre-GO source versus final actual source, executed after implementation; installed esbuild in-memory bundles share unchanged actual dependencies.',
  before_sha256:sha(before),after_sha256:sha(after),dependencies,results,
  limitations:'Synthetic local Node wall time; excludes input creation/bundling/serialization. No Worker CPU, I/O, high-cardinality, total capacity, SLO or customer/causal evidence. One warmup pair, three measured alternating pairs per size; all eight outputs per size identical. Remaining report scans/ring sorts/payload/model scope is open.'},null,2));
NODE

